public static GUPPriceComponentCodeGroup findbyGroup(
    GUPPriceComponentCodeGroupId _group,
    boolean _forupdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    GUPPriceComponentCodeGroup priceComponentCodeGroup;

    priceComponentCodeGroup.selectForUpdate(_forupdate);
    if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        priceComponentCodeGroup.concurrencyModel(_concurrencyModel);
    }

    select firstonly priceComponentCodeGroup
        where priceComponentCodeGroup.PriceComponentCodeGroup == _group;

    return priceComponentCodeGroup;
}

public static GUPPriceComponentCodeGroup find(
    RecId _recId ,
    boolean _forupdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    GUPPriceComponentCodeGroup priceComponentCodeGroup;

    priceComponentCodeGroup.selectForUpdate(_forupdate);
    if (_forupdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        priceComponentCodeGroup.concurrencyModel(_concurrencyModel);
    }

    select firstonly priceComponentCodeGroup
        where priceComponentCodeGroup.RecId == _recId;

    return priceComponentCodeGroup;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (this.PriceComponent != GUPPriceComponent::RetailDiscounts)
    {
        ret = checkFailed("@GlobalUnifiedPricing:GUPPriceComponentCodeGroupTypeNotSupported");
    }

    return ret;
}
